class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 2))
        self.__find = self._find
        self.__union = lambda x, y: self._union_fast(x, y)
        self.rank = [0] * (n + 3)

    def _find(self, x):
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        # Path compression
        while x != root:
            nxt = self.parent[x]
            self.parent[x] = root
            x = nxt
        return root

    def _union_fast(self, x, y):
        rx, ry = self._find(x), self._find(y)
        if rx != ry:
            # Union by rank
            if self.rank[rx] < self.rank[ry]:
                rx, ry = ry, rx
            self.parent[ry] = rx
            if self.rank[rx] == self.rank[ry]:
                self.rank[rx] += 1

