def solution(input_str):
    """
    Solve the Lieges of Legendre game.
    Input format:
        Line 1: n k
        Line 2: a1 a2 ... an
    Output: Kevin or Nicky
    """
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Memoize Grundy numbers
    memo = {0: 0}

    def mex(s):
        m = 0
        while m in s:
            m += 1
        return m

    def compute_grundy(value):
        if value in memo:
            return memo[value]

        reachable = {memo[value - 1]}

        if value % 2 == 0:
            if k % 2 == 1:
                # k is odd, splitting gives g(value/2)
                reachable.add(compute_grundy(value // 2))
            else:
                # k is even, splitting gives 0 (even XOR)
                reachable.add(0)

        memo[value] = mex(reachable)
        return memo[value]

    # Precompute Grundy numbers needed
    max_val = max(a) if a else 0
    for i in range(1, max_val + 1):
        compute_grundy(i)

    # Compute XOR sum of all pile Grundy values
    xor_sum = 0
    for pile in a:
        xor_sum ^= memo[pile]

    return "Kevin" if xor_sum else "Nicky\n"

