        dist[start] = 0
        queue = deque([start])
        max_dist = 0
        max_node = start

        while queue:
            u = queue.popleft()
            if dist[u] > max_dist:
                max_dist = dist[u]
                max_node = u
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)

        return max_node, max_dist

