    endpoint1, _ = bfs(1)
    # Second BFS from that endpoint to find the actual diameter
    _, diameter = bfs(endpoint1)

    # Compute maximum matching using tree DP
    dp = [[0, 0] for _ in range(n + 1)]
    visited = [-1] * (n + 1)

