    bridges = []

    def find_bridges(u, p=-1):
        visited[u] = True
        disc[u] = low[u] = timer[0]
        timer[0] += 1

        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                low[u] = min(low[u], disc[v])
            else:
                find_bridges(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((min(u, v), max(u, v)))

