                if (a == u and b == v) or (a == v and b == u):
                    edge_idx = i
                    break

            if edge_idx is None:
                continue
            if edge_used[edge_idx]:
                continue

            if visited[v]:
                # Back edge - orient from higher to lower discovery
                if discovery[0] > discovery.get(v, 0):
                    orientation[edge_idx] = (u, v)
                else:
                    orientation[edge_idx] = (v, u)
            else:
