            winner = (scored_a > scored_b) if a >= b else (scored_b > scored_a)
            if winner:
                new_a = current_a + scored_a if (sets_idx < sets_won_a or sets_idx < sets_won_b) else current_a
                new_b = current_b + scored_b if (sets_idx < sets_won_a or sets_idx < sets_won_b) else current_b
                if dfs(sets_idx + 1, 0, new_a, new_b) != "CONTINUE":
                    return list(yield_sets())

        return None

    return reachable

