        if v not in cached_gcd:
            visited = set()
            in_path = dict()
            path_len = 0

            def dfs(u, d, dp):
                nonlocal path_len
                visited.add(u)
                in_path[u] = (d, dp)
                has_cycle = False

                for w, _, wu in adj[u]:
                    if wu not in visited:
                        path_len = len(visited)
                        has_cycle = dfs(w, d + w, (u, dp + w))
                        if has_cycle:
                            return True
                    elif wu in in_path and dp + w != in_path[wu][1]:
                        # Cycle found
                        cycle_len = dp + w - in_path[wu][0]
                        path_len = min(path_len, d + cycle_len)
                        return True
                del in_path[u]
                return False

            dfs(v, 0, (0, 0))
            cached_gcd[v] = path_len
            cached_visited[v] = True

        if not cached_visited.get(v, False):
            return 'NO'

        if s % cached_gcd[v] == 0:
            return 'YES'
        return 'NO'

    for v, s, t in queries:
        if s == 0:
            results.append('YES')
        else:
            results.append(solve_query(v, s, t))

    return '\n'.join(results)

