    info_lines = lines[1 + n + 1:]
    vp, vs = map(int, info_lines[0].split())
    start_p = list(map(int, info_lines[1].split()))

    def dist(a, b):
        return ((a[0] - b[0])**2 + **(a[1] - b[1])2 + **(a[2] - b[2])2)**0.5

    def get_snitch_pos(t):
        """Get snitch position at time t"""
        time_acc = 0.0
        for i in range(n):
            d_i = dist(points[i], points[i+1])
            t_seg = d_i / vs
            if t >= time_acc + t_seg:
                time_acc += t_seg
            else:
                if t_seg > 0:
                    fraction = (t - time_acc) / t_seg
                    return [points[i][0] + fraction * (points[i+1][0] - points[i][0]),
                            points[i][1] + fraction * (points[i+1][1] - points[i][1]),
                            points[i][2] + fraction * (points[i+1][2] - points[i][2])]
                else:
                    return points[i]
        return points[-1]

    def can_catch(t):
        """Check if Harry can catch snitch at time t"""
        snitch_pos = get_snitch_pos(t)
        return dist(start_p, snitch_pos) <= vp * t

    # Binary search for minimum time
    total_dist = 0.0
    for i in range(n):
        total_dist += dist(points[i], points[i+1])
    total_time = total_dist / vs if vs > 0 else float('inf')

    low = 0.0
    high = total_time + 1e9 if total_time < float('inf') else 1e15

    # Binary search with sufficient iterations
    for _ in range(200):
        mid = (low + high) / 2
        if can_catch(mid):
            high = mid
        else:
            low = mid

    best_t = high

    # Find the actual catch position
    best_snitch_pos = get_snitch_pos(best_t)

    if can_catch(best_t):
        return f"YES\n{best_t:.15f}\n{best_snitch_pos[0]:.15f} {best_snitch_pos[1]:.15f} {best_snitch_pos[2]:.15f}\n"
