def compute_S(n):
    # Distinct values of 4*b + 9*c + 49*d where b+c+d <= n
    values = set()
    for b in range(n+1):
        for c in range(n-b+1):
            for d in range(n-b-c+1):
                val = 4*b + 9*c + 49*d
                values.add(val)
    return len(values)

