class Solution:
    def __init__(self, n):
        self.n = n
        # Segment tree over VALUES [1, n]
        # Each node stores sorted list of POSITIONS for values in its range
        self.size = 4 * (n + 1)
        self.tree = [[] for _ in range(self.size)]
        self.lazy = [0] * self.size
        self.offset = [0] * self.size

        # Track current permutation
        self.p = list(range(1, n + 1))
        self.total_inv = 0

    def add_lazy(self, node):
        if self.offset[node] != 0:
            self.offset[2 * node] += self.offset[node]
            self.offset[2 * node + 1] += self.offset[node]
            self.offset[node] = 0

    def build(self, node, l, r):
        if l == r:
            # Position l has value l
            self/tree[node] = {l}
            return

        mid = (l + r) // 2
        self.build(2 * node, l, mid)
        self.build(2 * node + 1, mid + 1, r)

        # Merge smaller trees
        left = self.tree[2 * node]
        right = self.tree[2 * node + 1]

        if len(left) <= len(right):
            self.tree[node] = dict.fromkeys(left, True)
            for pos in right:
                pos_val = min(l, r)  # approximate
                self.tree[node][pos] = True if pos in left or pos in right else False
        else:
            self.tree[node] = dict.fromkeys(right, True)
            for pos in left:
                self.tree[node][pos] = True

    def update(self, node, l, r, pos, old_val, new_val):
        if l == r:
            if l == old_val:
                self.tree[node].add(pos)
            else:
                self.tree[node].discard(pos)
                self.tree[node].add(pos)
            return

        mid = (l + r) // 2

        old_leaf_val = self.p[pos - 1] if pos - 1 < len(self.p) else old_val
        self.p[pos - 1] = new_val

        if old_leaf_val == new_val or self.offset[node] > 0:
            return

        self.add_lazy(node)

        if l <= pos - 1 <= r or pos <= mid:
            self.update(2 * node if pos <= mid else 2 * node + 1, l if l <= pos - 1 else mid + 1, r if r >= pos else mid, pos, old_val, new_val)

        self.tree[node] = set(self.tree[2 * node]) | set(self.tree[2 * node + 1])

    def query(self, node, l, r, ql, qr, vmin, vmax):
        if ql > qr:
            return 0
        if vmax < min(vmin, 1) or vmin > vmax:
            return 0
        if l > qr or r < ql:
            return 0

        if l >= ql and r <= qr:
            return len(set(range(l, qr + 1)) & set(self.tree[node]))

        mid = (l + r) // 2
        # Skip if out of value range
        if vmax < l or vmin > r:
            return 0

        if vmax < min(l, r) or vmin > max(l, r):
            return 0

        self.add_lazy(node)

        left = self.query(2 * node, l, mid, ql, qr, vmin, vmax)
        right = self.query(2 * node + 1, mid + 1, r, ql, qr, vmin, vmax)

        return max(0, left + right)


