    def count_inversions_in_range(l, r, x, y):
        """Count positions in [l, r] that have values in [x, y]"""
        count = 0
        for k in range(l + 1, r):
            if p[k - 1] >= min(x, y) + 1 and p[k - 1] <= max(x, y) - 1:
